CREATE TABLE `vmware_changes` (
  `change_id` int NOT NULL AUTO_INCREMENT COMMENT '변경 이력 ID',
  `vm_id` int NOT NULL COMMENT 'VM ID',
  `vm_name` varchar(255) NOT NULL COMMENT 'VM 이름',
  `cluster_host` varchar(255) NOT NULL COMMENT '클러스터 대표 호스트명',
  `hostname` varchar(255) NOT NULL COMMENT '호스트명',
  `ip` varchar(50) NOT NULL COMMENT 'IP 주소',
  `change_type` varchar(50) NOT NULL COMMENT '변경 유형 (new/modified/deleted)',
  `changes` text COMMENT '변경 내용 (JSON)',
  `review_status` varchar(50) DEFAULT '확인필요' COMMENT '검수 상태 (반영됨/확인필요/예외)',
  `reviewed_at` datetime DEFAULT NULL COMMENT '검수 날짜',
  `created_at` datetime DEFAULT NULL COMMENT '변경 발생 날짜',
  PRIMARY KEY (`change_id`),
  KEY `idx_vm_id` (`vm_id`),
  KEY `idx_vm_name` (`vm_name`),
  KEY `idx_review_status` (`review_status`),
  KEY `idx_change_type` (`change_type`)
) ENGINE=InnoDB AUTO_INCREMENT=3364 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='VMware 변경 이력';
